-- Real PostgreSQL, disposable synthetic records only.
begin;
select set_config('test.proof.fix',jsonb_build_object('latitude',12.971599,'longitude',77.594566,
 'accuracy_meters',8,'captured_at',clock_timestamp(),'consent_version','attendance-location-v1')::text,true);
-- Real synthetic 8x8 JPEG generated by Chromium canvas. Browser tests exercise
-- the complete camera encoding and QR pixel decoding separately.
select set_config('test.proof.photo',jsonb_build_object('jpeg_base64','',
 'captured_at',clock_timestamp(),'consent_version','attendance-photo-location-v1')::text,true);
select set_config('test.proof.previous',(select id::text from public.attendance_events where idempotency_key='e8000000-0000-4000-8000-000000000002'),true);
select set_config('test.proof.events',(select count(*)::text from public.attendance_events),true);

set role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001"}',true);
do $$ declare q jsonb;new_site uuid;begin
 -- Invalid area rolls back site creation and its audit.
 begin perform public.hr_save_attendance_site(null,null,'Must roll back','UTC',91,0,100,null);
   raise exception 'Invalid site was saved';exception when sqlstate 'PT422' then null;end;
 new_site:=public.hr_save_attendance_site(null,null,'QR test store','UTC',12.971599,77.594566,100,null);
 assert (public.hr_site_attendance_area(new_site)->>'configured')::boolean;
 assert length(public.hr_attendance_qr(new_site)->>'qr')>70;
 perform public.hr_save_site_attendance_area('e3000000-0000-4000-8000-000000000001',null,12.971599,77.594566,100);
 q:=public.hr_attendance_qr('e3000000-0000-4000-8000-000000000001');
 perform set_config('test.proof.qr',q->>'qr',true);
 begin perform public.hr_attendance_qr('e3000000-0000-4000-8000-000000000002');
   raise exception 'Foreign QR';exception when sqlstate 'PT404' then null;end;
end $$;
reset role;
do $$ begin assert not exists(select 1 from public.sites where name='Must roll back');end $$;
set role anon;
do $$ begin
 begin perform public.verify_attendance_qr(current_setting('test.proof.qr'));raise exception 'Anonymous QR';exception when insufficient_privilege then null;end;
end $$;
reset role;
set role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000004"}',true);
do $$ declare ev jsonb:=jsonb_build_object('qr',current_setting('test.proof.qr'),'photo',current_setting('test.proof.photo')::jsonb);
 fix jsonb:=current_setting('test.proof.fix')::jsonb;bad jsonb;receipt jsonb;
begin
 assert public.attendance_workspace()->>'evidence_required'='true';
 assert not(public.attendance_workspace()::text like '%'||current_setting('test.proof.qr')||'%');
 assert public.verify_attendance_qr(current_setting('test.proof.qr'))->>'site_id'='e3000000-0000-4000-8000-000000000001';
 begin perform public.hr_attendance_qr('e3000000-0000-4000-8000-000000000001');raise exception 'Employee fetched token';exception when sqlstate 'PT403' then null;end;
 begin perform public.record_attendance('clock_in',gen_random_uuid(),current_setting('test.proof.previous')::uuid,fix,'e4000000-0000-4000-8000-000000000004');raise exception 'Old API bypass';exception when sqlstate 'PT409' then assert sqlerrm='attendance_evidence_required';end;
 for bad in select unnest(array[null::jsonb,'{}'::jsonb]) loop
  begin perform public.record_attendance('clock_in',gen_random_uuid(),current_setting('test.proof.previous')::uuid,fix,'e4000000-0000-4000-8000-000000000004',bad);raise exception 'Missing proof accepted';exception when sqlstate 'PT422' then null;end;
 end loop;
 begin perform public.verify_attendance_qr('https://example.invalid');raise exception 'Invalid QR accepted';exception when sqlstate 'PT422' then assert sqlerrm='invalid_attendance_qr';end;
 begin perform public.record_attendance('clock_in',gen_random_uuid(),current_setting('test.proof.previous')::uuid,fix,'e4000000-0000-4000-8000-000000000004',ev||'{"qr":"wrong"}');raise exception 'Wrong QR accepted';exception when sqlstate 'PT422' then assert sqlerrm='invalid_attendance_qr';end;
 for bad in select unnest(array[
  (ev->'photo')||'{"jpeg_base64":"not-an-image"}',
  (ev->'photo')||'{"jpeg_base64":"/9j/2Q=="}',
  (ev->'photo')||jsonb_build_object('jpeg_base64',repeat('A',204804)),
  (ev->'photo')||jsonb_build_object('captured_at',clock_timestamp()-interval '3 minutes'),
  (ev->'photo')||'{"consent_version":"unapproved"}']) loop
  begin perform public.record_attendance('clock_in',gen_random_uuid(),current_setting('test.proof.previous')::uuid,fix,'e4000000-0000-4000-8000-000000000004',jsonb_set(ev,'{photo}',bad));raise exception 'Bad photo accepted';exception when sqlstate 'PT422' then null;end;
 end loop;
 begin perform public.record_attendance('clock_in',gen_random_uuid(),current_setting('test.proof.previous')::uuid,fix||'{"latitude":13}','e4000000-0000-4000-8000-000000000004',ev);raise exception 'Outside punch accepted';exception when sqlstate 'PT409' then assert sqlerrm='outside_store_area';end;
 receipt:=public.record_attendance('clock_in','ea000000-0000-4000-8000-000000000001',current_setting('test.proof.previous')::uuid,fix,'e4000000-0000-4000-8000-000000000004',ev);
 assert receipt->>'photo_saved'='true' and receipt->>'qr_verified'='true';
 perform set_config('test.proof.in',receipt->>'id',true);
 assert public.attendance_location_details((receipt->>'id')::uuid)->'clock_in'->'photo'->>'jpeg_base64'='';
 begin perform public.record_attendance('clock_in','ea000000-0000-4000-8000-000000000001',current_setting('test.proof.previous')::uuid,fix,'e4000000-0000-4000-8000-000000000004',jsonb_set(ev,'{photo,captured_at}',to_jsonb(clock_timestamp())));raise exception 'Replay changed photo';exception when sqlstate 'PT409' then assert sqlerrm='attendance_request_changed';end;
end $$;
reset role;
do $$ begin
 assert (select count(*) from public.attendance_events)=current_setting('test.proof.events')::int+1;
 assert (select count(*) from snr_private.attendance_evidence)=1;
 begin update snr_private.attendance_evidence set jpeg=decode('ffd8ffd9','hex');raise exception 'Proof rewritten';exception when raise_exception then if sqlerrm='Proof rewritten' then raise;end if;end;
end $$;
\echo 'PASS: atomic site setup, old API refusal, QR/photo validation, store enforcement and immutable evidence'

set role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001"}',true);
do $$ declare q jsonb;begin
 assert public.attendance_location_details(current_setting('test.proof.in')::uuid)->'clock_in'->'photo'->>'qr_verified'='true';
 q:=public.hr_attendance_qr('e3000000-0000-4000-8000-000000000001',true,1);
 assert q->>'qr'<>current_setting('test.proof.qr');
 perform set_config('test.proof.newqr',q->>'qr',true);
 begin perform public.hr_attendance_qr('e3000000-0000-4000-8000-000000000001',true,1);raise exception 'Stale rotation';exception when sqlstate 'PT409' then null;end;
end $$;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000004"}',true);
do $$ declare ev jsonb:=jsonb_build_object('qr',current_setting('test.proof.qr'),'photo',current_setting('test.proof.photo')::jsonb);
 fix jsonb:=current_setting('test.proof.fix')::jsonb;r jsonb;
begin
 assert public.record_attendance('clock_in','ea000000-0000-4000-8000-000000000001',current_setting('test.proof.previous')::uuid,fix,'e4000000-0000-4000-8000-000000000004',ev)->>'replayed'='true';
 begin perform public.record_attendance('clock_out',gen_random_uuid(),current_setting('test.proof.in')::uuid,fix,'e4000000-0000-4000-8000-000000000004',ev);raise exception 'Rotated QR accepted';exception when sqlstate 'PT422' then assert sqlerrm='invalid_attendance_qr';end;
 ev:=jsonb_set(ev,'{qr}',to_jsonb(current_setting('test.proof.newqr')));
 r:=public.record_attendance('clock_out','ea000000-0000-4000-8000-000000000002',current_setting('test.proof.in')::uuid,fix,'e4000000-0000-4000-8000-000000000004',ev);
 assert r->>'photo_saved'='true';
 assert public.attendance_location_details(current_setting('test.proof.in')::uuid)->'clock_out'->'photo'->>'qr_version'='2';
end $$;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002"}',true);
do $$ begin
 begin perform public.attendance_location_details(current_setting('test.proof.in')::uuid);raise exception 'Other employee photo';exception when sqlstate 'PT404' then null;end;
end $$;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000005"}',true);
do $$ begin
 begin perform public.attendance_location_details(current_setting('test.proof.in')::uuid);raise exception 'Foreign HR photo';exception when sqlstate 'PT404' then null;end;
end $$;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003"}',true);
do $$ begin
 begin perform public.attendance_location_details(current_setting('test.proof.in')::uuid);raise exception 'Supervisor photo';exception when sqlstate 'PT403' then null;end;
 begin perform public.hr_attendance_qr('e3000000-0000-4000-8000-000000000001');raise exception 'Supervisor fetched QR';exception when sqlstate 'PT403' then null;end;
 begin perform 1 from snr_private.attendance_evidence;raise exception 'Direct photo read';exception when insufficient_privilege then null;end;
end $$;
reset role;
do $$ begin
 assert (select count(*) from public.attendance_events)=current_setting('test.proof.events')::int+2;
 assert (select count(*) from snr_private.attendance_evidence)=2;
end $$;
\echo 'PASS: new QR rotation, exact retry, clock-out photo, employee/HR scopes and denied supervisor/private-table access'
rollback;
